    when: { job: 'dentist' },
    weight: 10,
    cooldown: 3,
    text: {
      fr: ["Un patient terrifié, bouche ouverte, te fixe avec des yeux de bête traquée. Tu approches la fraise. Il serre la mâchoire. Sur ton doigt.", "Tu dévitalises la molaire d'un rugbyman de 130 kg qui « n'a jamais eu peur de rien ». À la première vibration, il te mord l'index comme un pitbull."],
      en: ["A terrified patient, mouth open, stares at you like a hunted animal. You bring the drill closer. He clamps his jaw. On your finger.", "You're doing a root canal on a 290-pound rugby player who's 'never been scared of anything'. At the first buzz, he bites your index finger like a pit bull."],
    },
    choices: [
      { label: { fr: 'Hurler', en: 'Scream' }, text: { fr: "J'ai hurlé si fort que la salle d'attente s'est vidée. Il a lâché mon doigt, qui pendait un peu sur le côté. Il s'est excusé, et m'a remordu par réflexe en partant.", en: "I screamed so loud the waiting room emptied. He let go of my finger, which now hangs slightly sideways. He apologised, then bit me again on the way out, by reflex." }, fx: { health: -10, perf: -4, visual: 'gore' }, mood: 'cry' },
      { label: { fr: 'Lui pincer le nez', en: 'Pinch his nose' }, out: [
        { w: 2, text: { fr: "Il a ouvert la bouche pour respirer. Doigt récupéré, molaire soignée, dignité intacte. Technique transmise de génération en génération.", en: "He opened his mouth to breathe. Finger recovered, molar fixed, dignity intact. A technique passed down through generations." }, fx: { perf: 8, smarts: 2 }, mood: 'proud' },
        { w: 1, text: { fr: "Il a ouvert la bouche et vomi son petit-déj à la saucisse sur ma blouse, mes lunettes et l'aspiration. Qui s'est bouchée.", en: "He opened his mouth and puked his sausage breakfast all over my coat, my glasses and the suction tube. Which clogged." }, fx: { happy: -8, visual: 'poop' }, mood: 'sick' },
      ] },
      { label: { fr: 'Lancer la fraise', en: 'Fire up the drill' }, text: { fr: "J'ai démarré la fraise, toujours dans sa bouche. Il a lâché instantanément. Avis Google : « Brutal mais efficace. 5 étoiles. » Les masochistes du coin font la queue.", en: "I started the drill, still in his mouth. He let go instantly. Google review: 'Brutal but effective. 5 stars.' Every masochist in town is booking." }, fx: { perf: 6, karma: -4, money: 500 }, mood: 'proud' },
    ],
