    when: { job: 'priest' },
    weight: 9,
    cooldown: 3,
    text: {
      fr: ["Tu célèbres un mariage. « Si quelqu'un s'oppose à cette union, qu'il parle maintenant. » Trois personnes se lèvent. Dont la mère du marié. Et le marié.", "« Que celui qui s'oppose à ce mariage parle maintenant… » Un homme en sueur entre en courant, un bouquet à la main, et crie le prénom de la mariée. Elle hésite."],
      en: ["You're officiating a wedding. 'If anyone objects to this union, speak now.' Three people stand up. Including the groom's mother. And the groom.", "'If anyone objects, speak now…' A sweaty man bursts in with a bouquet and yells the bride's name. She hesitates."],
    },
    choices: [
      { label: { fr: 'Laisser parler', en: 'Let them speak' }, text: { fr: "Ça a duré deux heures. À la fin, la mariée a épousé le témoin et le marié est parti avec l'organiste. Deux couples pour le prix d'un. Les voies du Seigneur sont impénétrables.", en: "It took two hours. In the end the bride married the best man and the groom left with the organist. Two couples for the price of one. The Lord works in mysterious ways." }, fx: { perf: 6, happy: 6 }, mood: 'shock' },
      { label: { fr: 'Accélérer le « oui »', en: "Rush to the 'I do'" }, text: { fr: "« Personne ? Parfait, vous êtes mariés, allez en paix. » Ils sont mariés. Légalement. Ils ont l'air surpris. Moi aussi.", en: "'Nobody? Great, you're married, go in peace.' They're married. Legally. They look surprised. So am I." }, fx: { perf: 4, karma: -2, happy: 4 }, mood: 'happy' },
      { label: { fr: 'Proposer une médiation', en: 'Offer mediation' }, text: { fr: "Médiation dans la sacristie, avec du vin de messe. Tout le monde est ressorti réconcilié et légèrement pompette. Mariage célébré à 18 h.", en: "Mediation in the vestry, with communion wine. Everyone came out reconciled and slightly tipsy. Wedding held at 6 p.m." }, fx: { perf: 8, karma: 6 }, mood: 'happy' },
    ],
